const $=s=>document.querySelector(s),app=$('#app');
const moduleConfig=[
 ['Fundamentos cloud','01','D1','Qué es la nube, modelos, beneficios e infraestructura.'],
 ['Diseño y adopción','02','D1','Well-Architected, CAF, resiliencia y estrategias.'],
 ['IAM en profundidad','03','D2','Usuarios, grupos, roles, policies y protección de root.'],
 ['Seguridad y detección','04','D2','Detectar amenazas, vulnerabilidades y proteger aplicaciones.'],
 ['Cifrado y protección de datos','05','D2','Claves, certificados, secretos y cifrado.'],
 ['Compliance y gobernanza','06','D2','Auditoría, controles y organización de cuentas.'],
 ['Cómputo y contenedores','07','D3','Servidores, funciones, contenedores y capacidad.'],
 ['Almacenamiento y respaldo','08','D3','Objetos, bloques, archivos y recuperación.'],
 ['S3: clases y protección','09','D3','Clases, acceso, versiones y ciclo de vida.'],
 ['Bases de datos','10','D3','Relacional, NoSQL, memoria y casos de uso.'],
 ['Redes y seguridad de red','11','D3','VPC, subredes, rutas, SG, NACL y conectividad.'],
 ['Migración y transferencia','12','D3','Descubrimiento, conversión, traslado y seguimiento.'],
 ['IA y machine learning','13','D3','Qué tarea resuelve cada servicio de IA.'],
 ['Apps y mensajería','14','D3','Colas, notificaciones, eventos y flujos.'],
 ['Analítica y big data','15','D3','SQL, ETL, streaming y visualización.'],
 ['Usuarios finales y negocio','16','D3','Escritorios, aplicaciones, correo, atención e IoT.'],
 ['DevOps y desarrollo','17','D3','Herramientas, automatización e infraestructura como código.'],
 ['Monitoreo y estado','18','D3','Métricas, logs, alarmas, trazas y salud de AWS.'],
 ['Economía, billing y soporte','19','D4','TCO, compras, facturación, estimaciones y ayuda.']
];
const cats=moduleConfig.map(m=>m[0]);
const preferred=['Cloud computing: qué es la nube','IaaS, PaaS y SaaS','Modelos de despliegue: cloud, local e híbrido','Beneficios de la nube','Escalabilidad, elasticidad y agilidad','Infraestructura global: regiones, AZ y edge','Principios de diseño en la nube','Well-Architected: los seis pilares','AWS Cloud Adoption Framework (CAF)','Las 7 R de migración','AWS IAM','Autenticación y autorización','Root user: la identidad inicial','IAM users: usuarios','IAM groups: grupos de usuarios','IAM roles y credenciales temporales','IAM policies: Effect, Action y Resource','Evaluación de permisos: Allow y Deny','MFA, access keys y federación'];
const learningOrder=cats.flatMap(cat=>services.filter(s=>s.cat===cat).sort((a,b)=>{const ai=preferred.indexOf(a.name),bi=preferred.indexOf(b.name);return (ai<0?999:ai)-(bi<0?999:bi)||a.id-b.id}));
const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
let state={done:[],known:[],notes:{},attempts:[],challenges:[]};try{Object.assign(state,JSON.parse(localStorage.getItem('aws-flopy-v1')||'{}'))}catch{}
function save(){try{localStorage.setItem('aws-flopy-v1',JSON.stringify(state))}catch{alert('El navegador no pudo guardar tu progreso. Exportá una copia desde Guía y fuentes.')}}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let view='home',search='',category='Todas',onlyPending=false,flashIndex=0,flipped=false,flashCat='Todas',quiz=null;
const icons=['▧','▱','▥','⌁','◇','◉','⇄','✧','◎','◈'];
function intro(k,h,p){return `<div class="intro"><span class="eyebrow">${k}</span><h1>${h}</h1><p>${p}</p></div>`}
function go(v){view=v;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));render();window.scrollTo(0,0)}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();go('home')};
function render(){({home,library,cards,practice,quiz:renderQuiz,workshop,glossary,lesson:()=>lesson(current)})[view]()}
const progress=cat=>{const list=services.filter(s=>!cat||s.cat===cat);return Math.round(list.filter(s=>state.done.includes(s.id)).length/list.length*100)};
function home(){
 const next=learningOrder.find(s=>!state.done.includes(s.id))||learningOrder[0];
 const xp=state.done.length*10+state.known.length*3+state.challenges.length*15+state.attempts.reduce((n,a)=>n+a.score*2,0);
 app.innerHTML=intro('Tu guía de estudio · CLF-C02','Toda tu ruta. Un tema a la vez.','Entendé la nube desde cero, conectá servicios y practicá decisiones. Términos técnicos, explicados sin vueltas.')+
 `<section class="hero"><div><span class="eyebrow">DE LOS FUNDAMENTOS A LOS SERVICIOS</span><h2>Entender primero.<br>Recordar viene después.</h2><p>Lecciones breves, comparaciones y situaciones reales. Seguí la ruta o explorá el tema que necesitás.</p><button id="continue">${state.done.length?'Continuar mi recorrido':'Empezar desde cero'} ↗</button><p class="nextlesson">Sigue: ${next.name}</p></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orb">☁<small>ENTENDER</small></div><div class="orb">✓<small>DECIDIR</small></div></div></section>
 <section class="stats"><div class="stat"><span class="label">Tu recorrido</span><strong>${state.done.length}<small> / ${services.length} lecciones</small></strong><div class="bar"><div style="width:${progress()}%"></div></div></div><div class="stat"><span class="label">Puntos de aprendizaje</span><strong>${xp}<small> XP</small></strong><small>Lecturas, repaso y decisiones</small></div><div class="stat"><span class="label">Sesiones y desafíos</span><strong>${state.attempts.length+state.challenges.length}</strong><small>${state.known.length} tarjetas que ya dominás</small></div></section>
 <div class="activity-strip"><button id="tryworkshop"><b>⌘ Taller interactivo</b><span>Probá permisos y compará costos →</span></button><button id="tryquiz"><b>✓ Ponete a prueba</b><span>Escenarios con explicación →</span></button><button id="tryglossary"><b>Aa Glosario sin vueltas</b><span>Traducí el tecnicismo →</span></button></div>
 <div class="domain-strip"><span>D1 · Conceptos <b>24%</b></span><span>D2 · Seguridad <b>30%</b></span><span>D3 · Tecnología <b>34%</b></span><span>D4 · Costos y soporte <b>12%</b></span></div>
 <p class="muted">Los porcentajes son pesos de los dominios del examen, no de las lecciones de esta app. Diseño y talleres amplían la práctica conceptual.</p>
 <div class="sectionline"><h2>Tu mapa de aprendizaje</h2><span>${cats.length} módulos · ${services.length} lecciones</span></div>
 <section class="grid">${moduleConfig.map((m,i)=>`<button class="card category" data-cat="${m[0]}"><div class="row spread" style="width:100%"><span class="module-number">${m[1]}</span><span class="tag">${m[2]} · ${progress(m[0])}%</span></div><h3>${m[0]}</h3><p>${m[3]}</p><div class="bar" style="width:100%;margin-bottom:14px"><div style="width:${progress(m[0])}%"></div></div><div class="cardend"><span>${services.filter(s=>s.cat===m[0]).length} lecciones</span><span>Explorar →</span></div></button>`).join('')}</section>
 <div class="notice" style="margin-top:24px">Síntesis educativa independiente basada en el temario CLF-C02. No pretende reunir todo internet ni garantizar aprobación. Consultá las fuentes y los cambios antes de tu examen.</div>`;
 $('#continue').onclick=()=>openLesson(next.id);$('#tryworkshop').onclick=()=>go('workshop');$('#tryquiz').onclick=()=>go('quiz');$('#tryglossary').onclick=()=>go('glossary');
 document.querySelectorAll('.category').forEach(b=>b.onclick=()=>{category=b.dataset.cat;search='';go('library')});
}
function library(){app.innerHTML=intro('BIBLIOTECA DE CONCEPTOS Y SERVICIOS','La explicación que necesitás, sin dar mil vueltas.','Buscá un término o elegí un módulo. Seguí el orden sugerido dentro de cada tema.')+`<div class="tools"><input id="search" type="search" placeholder="Buscar: S3, permisos, bases de datos…" aria-label="Buscar servicios" value="${esc(search)}"><select id="category" aria-label="Filtrar por categoría"><option>Todas</option>${cats.map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select><button id="pending" aria-pressed="${onlyPending}">${onlyPending?'✓ ':''}Solo pendientes</button></div><div id="libraryresults"></div>`;$('#search').oninput=e=>{search=e.target.value;results()};$('#category').onchange=e=>{category=e.target.value;results()};$('#pending').onclick=()=>{onlyPending=!onlyPending;library()};results()}
function results(){const found=learningOrder.filter(s=>(category==='Todas'||s.cat===category)&&(!onlyPending||!state.done.includes(s.id))&&normalize(s.name+' '+s.definition+' '+s.cat+' '+(s.use||'')).includes(normalize(search)));$('#libraryresults').innerHTML=`<div class="sectionline"><span>${found.length} lecciones encontradas</span></div><section class="grid">${found.map(s=>`<button class="card service" data-id="${s.id}"><div class="row"><span class="tag">${s.kind==='concept'?'Concepto':'Servicio'}</span>${s.scope==='complemento'?'<span class="tag gold">Complementario</span>':''}</div><h3>${s.name}</h3><p>${s.memory}</p><div class="cardend"><span>${state.done.includes(s.id)?'✓ Estudiado':'Lectura + práctica'}</span><span>Aprender →</span></div></button>`).join('')}</section>${!found.length?'<div class="empty">No encontramos coincidencias. Probá con otro término o categoría.</div>':''}`;document.querySelectorAll('.service').forEach(b=>b.onclick=()=>openLesson(+b.dataset.id))}
let current=0,lessonStep=0,showAllSections=false;
function openLesson(id){current=id;lessonStep=0;go('lesson')}
function lesson(id){
 const s=services[id],position=learningOrder.findIndex(x=>x.id===id),src=studyMeta.sources[s.source]||studyMeta.sources.exam;
 const labels=['Definición','Para qué sirve','Cómo funciona por dentro','Analogía','Casos de uso típicos','Alternativas y comparación'];
 const originalTable=s.table?`<details class="technical-details"><summary>Ampliar: comparación específica del tema</summary><div class="compare-table"><table><thead><tr>${s.table.headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${s.table.rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`:'';
 const contents=[
 `<p class="lead-definition">${s.definition}</p><div class="memory"><span class="eyebrow">QUÉ NECESITÁS IDENTIFICAR</span><p>${s.memory}</p></div>`,
 `<p>${s.use||s.memory}</p><div class="lesson-purpose"><b>La pregunta de decisión</b><p>¿Mi problema coincide con esta función? Si necesitás otra cosa, revisá las opciones de la última sección.</p></div>`,
 `<p class="muted">Recorrido funcional simplificado: describe pasos y responsabilidades, no detalles privados de implementación de AWS.</p><ol class="mechanism-flow">${s.mechanics.map((x,i)=>`<li><span>${i+1}</span><p>${x}.</p></li>`).join('')}</ol>${s.points?.length?`<details class="technical-details"><summary>Claves técnicas para afianzar</summary><ul class="keypoints">${s.points.map(x=>`<li>${x}</li>`).join('')}</ul></details>`:''}`,
 `<div class="analogy-box"><span aria-hidden="true" class="analogy-symbol">◈</span><p>${s.analogy}</p></div><div class="analogy-limit"><b>Dónde termina la analogía</b><p>${s.analogyBoundary}</p></div>`,
 `<ul class="usecase-list">${s.useCases.map(x=>`<li><span aria-hidden="true">✓</span><div>${x}</div></li>`).join('')}</ul><section class="example"><h3>Un ejemplo concreto</h3><p>${s.example}</p></section>`,
 `<p class="muted">No todo lo relacionado compite entre sí. La columna «Relación» distingue opciones, herramientas y servicios que se usan juntos.</p><div class="compare-table"><table><thead><tr><th>Opción</th><th>Diferencia o cuándo elegirla</th><th>Relación</th></tr></thead><tbody>${s.alternatives.map(x=>`<tr><td><strong>${x.option}</strong></td><td>${x.difference}</td><td><span class="tag">${x.relation}</span></td></tr>`).join('')}</tbody></table></div><div class="related-box"><b>Cómo se conecta con el resto</b><p>${s.related}</p></div>${originalTable}`
 ];
 app.innerHTML=`<div class="lesson"><button class="back" id="back">← Volver al módulo</button><div class="lessonhead"><span class="eyebrow">${s.cat}</span><h1>${s.name}</h1><div class="row"><span class="tag">${state.done.includes(id)?'✓ Estudiado':s.kind==='concept'?'Concepto':'Servicio'}</span>${s.scope==='complemento'?'<span class="tag gold">Tema complementario</span>':''}<span class="muted">${position+1} de ${services.length} en tu recorrido</span></div></div>
 <article class="lessonbody six-part"><div class="reading-controls"><span class="eyebrow">UNA IDEA, SEIS PERSPECTIVAS</span><button id="reading-mode" class="smallbtn" aria-pressed="${showAllSections}">${showAllSections?'Leer paso a paso':'Ver todo junto'}</button></div><div class="lesson-step-nav" role="group" aria-label="Secciones de la lección">${labels.map((label,i)=>`<button data-section="${i}" aria-pressed="${i===lessonStep}"><span>${String(i+1).padStart(2,'0')}</span>${label}</button>`).join('')}</div>
 <div id="reading-sections">${labels.map((label,i)=>`<section class="reading-section" id="lesson-section-${i}" ${showAllSections||i===lessonStep?'':'hidden'}><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${showAllSections?'SEIS PERSPECTIVAS':'PASO '+(i+1)+' DE 6'}</span><h2>${label}</h2>${contents[i]}</section>`).join('')}</div>
 ${showAllSections?'':`<div class="row spread section-pager"><button id="section-prev" ${lessonStep===0?'disabled':''}>← Paso anterior</button><span>${lessonStep+1} / 6</span><button class="primary" id="section-next">${lessonStep===5?'Ir al mini desafío ↓':'Siguiente paso →'}</button></div>`}
 <div class="pitfall"><strong>⚑ Ojo con esta diferencia</strong><p>${s.pitfall}</p></div>
 <section class="checkpoint" id="lesson-checkpoint"><span class="eyebrow">TU TURNO · RECORDAR Y DECIDIR</span><h3>¿Lo podés aplicar?</h3><p>Hacé una decisión breve y comprobá el porqué.</p><button id="quick">Resolver mini desafío →</button><div id="lessoncheck"></div></section>
 <label class="noteslabel" for="note">Mis apuntes, con mis palabras</label><textarea id="note" class="note" placeholder="¿Qué problema resuelve? ¿Cómo funciona? ¿Con qué lo compararías?">${esc(state.notes[id]||'')}</textarea><p class="muted" id="notestatus">Se guardan en este navegador.</p>
 <button class="primary" id="mark">${state.done.includes(id)?'✓ Estudiado · desmarcar':'Marcar como estudiado · +10 XP'}</button>
 <div class="lesson-source"><span>Referencia de estudio · ${studyMeta.reviewed}</span><a href="${src[1]}" target="_blank" rel="noopener">${src[0]} ↗</a><small>Precios, planes y disponibilidad pueden cambiar. Los recorridos internos son modelos funcionales simplificados.</small></div>
 <div class="row spread" style="margin-top:25px"><button id="prev" ${position===0?'disabled':''}>← Lección anterior</button><button id="next" ${position===learningOrder.length-1?'disabled':''}>Lección siguiente →</button></div></article></div>`;
 const switchSection=i=>{lessonStep=i;lesson(id);$('.reading-controls').scrollIntoView({block:'start'})};
 document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{const i=+b.dataset.section;if(showAllSections){lessonStep=i;$('#lesson-section-'+i).scrollIntoView({block:'start'})}else switchSection(i)});
 $('#reading-mode').onclick=()=>{showAllSections=!showAllSections;lesson(id);$('.reading-controls').scrollIntoView({block:'start'})};
 if(!showAllSections){$('#section-prev').onclick=()=>switchSection(lessonStep-1);$('#section-next').onclick=()=>{if(lessonStep<5)switchSection(lessonStep+1);else $('#lesson-checkpoint').scrollIntoView({block:'start'})}};
 $('#back').onclick=()=>{category=s.cat;go('library')};$('#note').oninput=e=>{state.notes[id]=e.target.value;save();$('#notestatus').textContent='✓ Apunte guardado.'};$('#mark').onclick=()=>{state.done=state.done.includes(id)?state.done.filter(x=>x!==id):[...state.done,id];save();lesson(id)};
 $('#prev').onclick=()=>openLesson(learningOrder[position-1].id);$('#next').onclick=()=>openLesson(learningOrder[position+1].id);
 $('#quick').onclick=()=>{const q=makeQuestion(s);$('#lessoncheck').innerHTML=`<h3>${q.prompt}</h3><div class="answers">${q.options.map(o=>`<button class="answer" data-a="${o.id}">${o.name}</button>`).join('')}</div><div id="miniresult" role="status"></div>`;
 document.querySelectorAll('[data-a]').forEach(b=>b.onclick=()=>{const right=+b.dataset.a===id;b.classList.add(right?'correct':'wrong');$('#miniresult').innerHTML=`<div class="feedback ${right?'':'bad'}"><strong>${right?'✓ Bien pensado.':'Revisá la distinción.'}</strong> ${q.explanation}</div>`;if(right)document.querySelectorAll('[data-a]').forEach(x=>x.disabled=true)})};
}
function shuffled(a){return [...a].sort(()=>Math.random()-.5)}
function makeQuestion(s){
 if(s.check)return {s,prompt:s.check.q,explanation:s.check.why,options:shuffled([{id:s.id,name:s.check.correct},...s.check.wrong.map((name,i)=>({id:-(i+1),name}))])};
 let pool=services.filter(x=>x.cat===s.cat&&x.id!==s.id);if(pool.length<3)pool=services.filter(x=>x.id!==s.id);
 return {s,prompt:s.definition+' ¿Qué servicio o concepto describe?',explanation:s.name+': '+s.memory,options:shuffled([s,...shuffled(pool).slice(0,3)])};
}
function cards(){const pool=learningOrder.filter(s=>flashCat==='Todas'||s.cat===flashCat);flashIndex=(flashIndex+pool.length)%pool.length;const s=pool[flashIndex];app.innerHTML=intro('REPASO ACTIVO','Primero recordá. Después mirá.','Intentá explicar el servicio en voz alta antes de dar vuelta la tarjeta.')+`<div class="tools"><select id="flashcat" class="catselect" aria-label="Categoría de tarjetas"><option>Todas</option>${cats.map(c=>`<option ${c===flashCat?'selected':''}>${c}</option>`).join('')}</select><button id="shuffle">Mezclar tarjeta ↻</button></div><div class="flashwrap"><div class="progresshead"><span>${s.cat}</span><span>${flashIndex+1} / ${pool.length}</span></div><div class="flash-scene"><section class="flash-turn ${flipped?'is-flipped':''}" id="flash-turn" aria-label="Tarjeta de repaso"><div class="flash flash-face flash-front" aria-hidden="${flipped}"><span class="eyebrow">¿CÓMO LO EXPLICARÍAS?</span><h2>${s.name}</h2><p>¿Qué es y en qué situación lo elegirías?</p></div><div class="flash flash-face flash-back" aria-hidden="${!flipped}"><span class="eyebrow">LA RESPUESTA</span><h2>${s.name}</h2><p>${s.definition}</p><div class="memory">${s.memory}</div></div></section></div><button class="primary flip-control" id="flip" aria-pressed="${flipped}" aria-controls="flash-turn">${flipped?'Ver pregunta':'Revelar explicación'} ↻</button><div class="row spread" style="margin-top:20px"><button id="flashprev">← Anterior</button><button id="known" class="${state.known.includes(s.id)?'primary':''}">${state.known.includes(s.id)?'✓ Ya lo sé · desmarcar':'Ya lo sé ✓'}</button><button id="flashnext">Siguiente →</button></div><p class="muted">¿Te cuesta? <a href="#" id="readlesson">Volvé a la lección completa.</a></p></div>`;$('#flashcat').onchange=e=>{flashCat=e.target.value;flashIndex=0;flipped=false;cards()};$('#flip').onclick=()=>{flipped=!flipped;$('#flash-turn').classList.toggle('is-flipped',flipped);$('.flash-front').setAttribute('aria-hidden',String(flipped));$('.flash-back').setAttribute('aria-hidden',String(!flipped));$('#flip').setAttribute('aria-pressed',String(flipped));$('#flip').textContent=(flipped?'Ver pregunta':'Revelar explicación')+' ↻'};$('#flashprev').onclick=()=>{flashIndex--;flipped=false;cards()};$('#flashnext').onclick=()=>{flashIndex++;flipped=false;cards()};$('#shuffle').onclick=()=>{flashIndex=Math.floor(Math.random()*pool.length);flipped=false;cards()};$('#known').onclick=()=>{state.known=state.known.includes(s.id)?state.known.filter(x=>x!==s.id):[...state.known,s.id];save();cards()};$('#readlesson').onclick=e=>{e.preventDefault();openLesson(s.id)}}
const challenges=[{name:'Una app de notas serverless',context:'Una persona escribe una nota desde el navegador. La aplicación recibe la solicitud, ejecuta la lógica y conserva la nota sin administrar servidores.',steps:[['Entrada HTTPS de la aplicación','Amazon API Gateway',['Amazon API Gateway','Amazon Route 53','Amazon SQS'],'API Gateway administra la API; Route 53 resuelve nombres y SQS almacena mensajes.'],['Ejecutar el código que valida la nota','AWS Lambda',['AWS Lambda','Amazon S3','AWS CloudTrail'],'Lambda ejecuta código por eventos; S3 almacena objetos y CloudTrail audita actividad.'],['Guardar las notas por identificador','Amazon DynamoDB',['Amazon DynamoDB','Amazon SNS','Amazon CloudFront'],'DynamoDB guarda datos NoSQL; SNS notifica y CloudFront distribuye contenido.']]},{name:'Procesar pedidos sin perder el ritmo',context:'Una tienda recibe ráfagas de pedidos. Necesita guardarlos pendientes, procesarlos a su ritmo y avisar a varios suscriptores cuando un pedido termina.',steps:[['Retener pedidos pendientes hasta procesarlos','Amazon SQS',['Amazon SQS','Amazon SNS','Amazon Route 53'],'SQS desacopla productores y consumidores con una cola de trabajo.'],['Procesar mensajes sin administrar servidores','AWS Lambda',['AWS Lambda','AWS WAF','Amazon EFS'],'Lambda puede consumir mensajes de SQS. Se deben manejar reintentos e idempotencia para procesar con seguridad.'],['Difundir la notificación a suscriptores','Amazon SNS',['Amazon SNS','Amazon RDS','AWS Config'],'SNS distribuye una publicación a suscriptores. SQS y SNS se complementan, no son equivalentes.']]},{name:'¿Quién cambió la configuración?',context:'Cambió la configuración de un recurso. Tenés que investigar quién realizó la acción, revisar cómo quedó configurado y observar si la aplicación tiene errores.',steps:[['Identificar la acción y quién la realizó','AWS CloudTrail',['AWS CloudTrail','Amazon CloudWatch','AWS Config'],'CloudTrail audita actividad y llamadas a API.'],['Revisar historial de configuración y reglas','AWS Config',['AWS Config','Amazon GuardDuty','Amazon SNS'],'Config registra configuración y evalúa reglas para recursos compatibles.'],['Revisar métricas y registros de la aplicación','Amazon CloudWatch',['Amazon CloudWatch','AWS Artifact','AWS KMS'],'CloudWatch ayuda a observar rendimiento y registros, según lo recopilado.']]},{name:'Elegir dónde guardar cada cosa',context:'Una aplicación necesita guardar fotos, disponer de un disco para un servidor Linux y compartir archivos entre varios servidores Linux.',steps:[['Almacenar fotos como objetos','Amazon S3',['Amazon S3','Amazon EBS','Amazon EFS'],'S3 guarda objetos en buckets; no es un disco adjunto a una instancia.'],['Dar un disco persistente a una instancia EC2','Amazon EBS',['Amazon EBS','Amazon S3','Amazon CloudFront'],'EBS aporta almacenamiento en bloques dentro de una zona.'],['Compartir archivos por red entre servidores Linux','Amazon EFS',['Amazon EFS','Amazon EBS','Amazon DynamoDB'],'EFS aporta un sistema de archivos compartido y elástico.']]},{name:'Detectar y proteger',context:'Un equipo necesita analizar amenazas de la cuenta, filtrar ataques web y gestionar contraseñas de la aplicación fuera del código.',steps:[['Detectar actividad potencialmente maliciosa','Amazon GuardDuty',['Amazon GuardDuty','Amazon Inspector','Amazon Macie'],'GuardDuty detecta amenazas; Inspector busca vulnerabilidades y Macie identifica datos sensibles en S3.'],['Filtrar solicitudes web según reglas','AWS WAF',['AWS WAF','AWS KMS','Amazon SQS'],'WAF filtra solicitudes HTTP/HTTPS en recursos compatibles.'],['Guardar y recuperar credenciales de base de datos','AWS Secrets Manager',['AWS Secrets Manager','AWS Artifact','Amazon Route 53'],'Secrets Manager gestiona secretos y puede ayudar a rotarlos.']]},{name:'Red pública y recursos privados',context:'Querés una entrada web pública y servidores que puedan descargar actualizaciones sin recibir conexiones entrantes de internet directamente.',steps:[['Recibir y distribuir solicitudes web','Elastic Load Balancing',['Elastic Load Balancing','AWS CloudTrail','Amazon EFS'],'Un balanceador público puede distribuir tráfico a destinos privados configurados correctamente.'],['Permitir salida IPv4 de servidores privados','NAT Gateway',['NAT Gateway','Internet Gateway directo','Amazon Route 53'],'En el diseño habitual, una ruta privada apunta a NAT Gateway público; NAT necesita conectividad a internet a través de IGW. No publica el servidor privado.'],['Filtrar tráfico permitido hacia recursos','Security Group',['Security Group','AWS Cost Explorer','Amazon Polly'],'Un Security Group mantiene estado y controla tráfico del recurso. Las rutas también deben estar bien configuradas.']]}];
challenges.push(...[{"name": "La base adecuada para cada dato", "context": "Una tienda combina pedidos relacionados, sesiones por identificador y consultas repetidas que necesitan baja latencia. Elegí un almacenamiento para cada necesidad.", "steps": [["Pedidos con relaciones y transacciones SQL", "Amazon RDS", ["Amazon RDS", "Amazon DynamoDB", "Amazon ElastiCache"], "RDS ofrece motores relacionales y SQL. DynamoDB exige diseñar accesos NoSQL; ElastiCache no reemplaza aquí la base persistente de pedidos."], ["Sesiones consultadas por una clave conocida a gran escala", "Amazon DynamoDB", ["Amazon DynamoDB", "Amazon RDS", "Amazon ElastiCache"], "DynamoDB encaja con acceso clave-valor y persistencia administrada. RDS puede guardar sesiones, pero agrega un modelo relacional innecesario en este escenario; una caché requiere considerar persistencia y pérdidas."], ["Cachear resultados para descargar la base principal", "Amazon ElastiCache", ["Amazon ElastiCache", "Amazon RDS", "Amazon DynamoDB"], "ElastiCache mantiene datos en memoria para acceso rápido. RDS y DynamoDB pueden ser bases de origen, pero no cumplen el papel de caché en memoria solicitado."]]}, {"name": "IA: de un documento a una voz", "context": "Un equipo quiere digitalizar facturas, transcribir entrevistas y convertir texto en audio. Identificá el servicio por la tarea, no por su nombre.", "steps": [["Extraer texto, campos y tablas de facturas escaneadas", "Amazon Textract", ["Amazon Textract", "Amazon Rekognition", "Amazon Transcribe"], "Textract extrae texto y estructura de documentos. Rekognition se orienta al análisis visual; Transcribe convierte audio en texto."], ["Convertir una entrevista grabada en texto", "Amazon Transcribe", ["Amazon Transcribe", "Amazon Polly", "Amazon Rekognition"], "Transcribe realiza reconocimiento de voz. Polly hace el sentido inverso: texto a voz. Rekognition analiza imágenes y video."], ["Leer en voz alta una explicación escrita", "Amazon Polly", ["Amazon Polly", "Amazon Textract", "Amazon Rekognition"], "Polly sintetiza voz desde texto. Textract extrae información de documentos; Rekognition identifica contenido visual."]]}, {"name": "Costos: antes, durante y al superar un límite", "context": "Vas a lanzar una app. Necesitás estimar el costo, analizar luego el gasto real y recibir avisos al acercarte a tu presupuesto.", "steps": [["Estimar una configuración antes de crear recursos", "AWS Pricing Calculator", ["AWS Pricing Calculator", "AWS Cost Explorer", "AWS Budgets"], "Pricing Calculator estima con los supuestos que ingresás. Cost Explorer analiza costos y uso; Budgets controla objetivos y avisos. Una estimación no garantiza la factura final."], ["Investigar qué servicio generó el gasto del mes", "AWS Cost Explorer", ["AWS Cost Explorer", "AWS Pricing Calculator", "AWS Budgets"], "Cost Explorer permite explorar costos y uso por dimensiones. Calculator estima escenarios; Budgets avisa sobre objetivos, no sustituye ese análisis."], ["Recibir un aviso por gasto real o previsto frente a un objetivo", "AWS Budgets", ["AWS Budgets", "AWS Cost Explorer", "AWS Pricing Calculator"], "Budgets compara con presupuestos y puede notificar. No impone por defecto un tope que detenga todo gasto. Cost Explorer analiza; Calculator estima."]]}]);
let challengeIndex=-1;
function practice(){if(challengeIndex<0){app.innerHTML=intro('LABORATORIO DE DECISIONES','Armá la solución, pieza por pieza.','Elegí servicios para resolver una necesidad y descubrí por qué encajan.')+`<div class="notice">Simulaciones educativas: no conectan con tu cuenta AWS ni crean recursos.</div><section class="grid" style="margin-top:24px">${challenges.map((c,i)=>`<button class="card" data-ch="${i}"><span class="tag ${state.challenges.includes(i)?'':'gold'}">${state.challenges.includes(i)?'✓ Completado':'3 decisiones'}</span><h3>${c.name}</h3><p>${c.context}</p><div class="cardend"><span>Práctica guiada</span><span>Resolver →</span></div></button>`).join('')}</section>`;document.querySelectorAll('[data-ch]').forEach(b=>b.onclick=()=>{challengeIndex=+b.dataset.ch;practice()});return}const c=challenges[challengeIndex];app.innerHTML=`<button class="back" id="allch">← Todos los desafíos</button>`+intro('DESAFÍO '+(challengeIndex+1),c.name,c.context)+`<div class="challenge"><section class="panel"><span class="eyebrow">TU SOLUCIÓN</span>${c.steps.map((s,i)=>`<div class="step" id="step${i}"><label for="sel${i}">${i+1}. ${s[0]}</label><select id="sel${i}"><option value="">Elegí una pieza…</option>${shuffled(s[2]).map(n=>`<option>${n}</option>`).join('')}</select><div id="why${i}" class="muted"></div></div>`).join('')}<button class="primary" id="checkch">Comprobar mi solución</button><div id="chstatus" role="status"></div></section><section class="panel"><span class="eyebrow">CÓMO SE CONECTAN LAS PIEZAS</span><h2>Tu mapa de decisiones</h2><p>Elegí cada componente. El mapa se completa con tu propuesta.</p><div class="flow" id="flow"></div><p class="muted">La secuencia representa decisiones didácticas, no necesariamente un flujo de tráfico entre todos los componentes.</p></section></div>`;$('#allch').onclick=()=>{challengeIndex=-1;practice()};const flow=()=>{$('#flow').innerHTML=c.steps.map((s,i)=>`${i?'<span>↓</span>':''}${esc($('#sel'+i).value||'Paso '+(i+1)+' · por definir')}`).join('')};c.steps.forEach((s,i)=>$('#sel'+i).onchange=flow);flow();$('#checkch').onclick=()=>{let n=0;c.steps.forEach((s,i)=>{const ok=$('#sel'+i).value===s[1];if(ok)n++;$('#step'+i).className='step '+(ok?'good':'bad');$('#why'+i).textContent=(ok?'✓ Correcto. ':'↻ Revisá esta decisión. ')+s[3]});$('#chstatus').innerHTML=`<div class="feedback ${n===3?'':'bad'}">${n}/3 decisiones correctas. ${n===3?'¡Solución completada! Podés probar otro desafío.':'Leé las explicaciones, ajustá las piezas y volvé a comprobar.'}</div>`;if(n===3&&!state.challenges.includes(challengeIndex)){state.challenges.push(challengeIndex);save()}}}
function renderQuiz(){if(!quiz){app.innerHTML=intro('PRACTICÁ EL CRITERIO','¿Qué servicio resuelve este caso?','Preguntas cortas para conectar necesidades con servicios. Recibí una explicación después de cada respuesta.')+`<section class="quizbox"><span class="tag">PRÁCTICA ORIGINAL · SIN TIEMPO LÍMITE</span><h2>Una sesión pequeña.<br>Hasta diez oportunidades para aprender.</h2><p>Seleccioná un tema o mezclá categorías. Al terminar, revisá tus respuestas y volvé a las lecciones que necesites.</p><div class="tools"><select id="quizcat" aria-label="Categoría del cuestionario"><option>Todas</option>${cats.map(c=>`<option>${c}</option>`).join('')}</select><button class="primary" id="startquiz">Comenzar práctica →</button></div><p class="muted">Esto es práctica de reconocimiento, no un simulacro completo del examen ni una predicción de tu puntaje oficial.</p>${state.attempts.length?`<p class="muted">Última sesión: ${state.attempts.at(-1).score}/${state.attempts.at(-1).total} correctas.</p>`:''}</section>`;$('#startquiz').onclick=()=>{const cat=$('#quizcat').value;const eligible=services.filter(s=>(cat==='Todas'||s.cat===cat)&&s.check);const candidates=eligible.length?eligible:services.filter(s=>cat==='Todas'||s.cat===cat);quiz={questions:shuffled(candidates).slice(0,10).map(makeQuestion),index:0,answers:[]};renderQuiz()};return}if(quiz.index>=quiz.questions.length){const score=quiz.answers.filter(Boolean).length;app.innerHTML=intro('SESIÓN COMPLETADA','Cada decisión te enseña algo.','Revisá los conceptos que todavía necesitás afianzar.')+`<section class="quizbox"><div class="results">${score}<span class="muted"> / ${quiz.questions.length}</span></div><p style="text-align:center">${score===quiz.questions.length?'¡Muy bien! Probá otra categoría para seguir conectando conceptos.':'Los errores te muestran qué repasar a continuación.'}</p>${quiz.questions.map((q,i)=>`<div class="row spread" style="border-top:1px solid var(--line);padding:12px 0"><span>${quiz.answers[i]?'✓':'↻'} ${q.s.name}</span><button class="smallbtn" data-review="${q.s.id}">Ver lección</button></div>`).join('')}<button class="primary" id="newquiz">Otra sesión</button></section>`;document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>openLesson(+b.dataset.review));$('#newquiz').onclick=()=>{quiz=null;renderQuiz()};return}const q=quiz.questions[quiz.index],answered=quiz.answers.length>quiz.index;app.innerHTML=`<div class="progresshead"><span>PRÁCTICA DE RECONOCIMIENTO</span><span>Pregunta ${quiz.index+1} de ${quiz.questions.length}</span></div><div class="bar"><div style="width:${quiz.index/quiz.questions.length*100}%"></div></div><section class="quizbox"><span class="tag">${q.s.cat}</span><h2>${q.prompt}</h2><p>Elegí la mejor respuesta para este caso.</p><div class="answers">${q.options.map(o=>`<button class="answer" data-option="${o.id}" ${answered?'disabled':''}>${o.name}</button>`).join('')}</div><div id="quizfeedback" role="status"></div><button id="nextq" class="primary" hidden>Continuar →</button></section>`;function feedback(){document.querySelectorAll('[data-option]').forEach(b=>{b.disabled=true;if(+b.dataset.option===q.s.id)b.classList.add('correct')});$('#quizfeedback').innerHTML=`<div class="feedback ${quiz.answers[quiz.index]?'':'bad'}"><strong>${quiz.answers[quiz.index]?'✓ Correcto':'La respuesta es '+(q.s.check?.correct||q.s.name)}.</strong><br>${q.explanation}<br><em>${q.s.memory}</em></div>`;$('#nextq').hidden=false}document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{if(quiz.answers.length>quiz.index)return;const ok=+b.dataset.option===q.s.id;quiz.answers.push(ok);if(!ok)b.classList.add('wrong');feedback()});if(answered)feedback();$('#nextq').onclick=()=>{quiz.index++;if(quiz.index===quiz.questions.length){state.attempts.push({score:quiz.answers.filter(Boolean).length,total:quiz.questions.length,date:new Date().toISOString()});save()}renderQuiz()}}
$('#sourcebtn').onclick=()=>$('#sources').showModal();$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='mi-progreso-aws.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('#importbtn').onclick=()=>$('#importfile').click();$('#importfile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error();const s=JSON.parse(await f.text());if(!['done','known','attempts','challenges'].every(k=>Array.isArray(s[k]))||!s.notes||typeof s.notes!=='object'||Array.isArray(s.notes))throw Error();if(![...s.done,...s.known].every(id=>Number.isInteger(id)&&services[id])||!s.challenges.every(id=>Number.isInteger(id)&&challenges[id])||!Object.values(s.notes).every(v=>typeof v==='string')||!s.attempts.every(a=>Number.isInteger(a.score)&&Number.isInteger(a.total)&&a.score>=0&&a.score<=a.total&&a.total<=100))throw Error();state={done:[...new Set(s.done)],known:[...new Set(s.known)],notes:s.notes,attempts:s.attempts,challenges:[...new Set(s.challenges)]};save();render();$('#importstatus').textContent='✓ Progreso importado correctamente.'}catch{$('#importstatus').textContent='No se pudo importar. Elegí una copia de progreso exportada por esta app.'}e.target.value=''};
go('home');
